/* DSM Telemarketing. Uses the existing DSM components, typography and navigation. */
let tmState={boot:null,tab:'sales',person:'',filters:{q:'',brand:'ALL',big:'ALL',region:'ALL',state:'ALL'},activity:null,order:null,admin:null,adminPerson:'',config:null};
function tmMenuAllowed(page,role){
 if(page==='tmfu')return false;
 if(page==='tmorder')return ['TELEMARKETING','SALES','ASM','RGM','ADMIN','SUPER ADMIN'].includes(role);
 if(page==='tmactivity'&&['ASM','RGM'].includes(role)&&BOOT?.user?.tmVisible===false)return false;
 if(page==='tmactivity')return ['TELEMARKETING','ASM','RGM','ADMIN','SUPER ADMIN','HEAD OF SALES','CHIEF OPERATING OFFICER','CHIEF COMMERCIAL OFFICER','BOARD OF DIRECTOR'].includes(role);
 if(role==='TELEMARKETING')return !['tim','admin','ai','tmactivity'].includes(page);
 return page!=='ai';
}
function tmResetIdentity(){tmState={boot:null,tab:'sales',person:'',filters:{q:'',brand:'ALL',big:'ALL',region:'ALL',state:'ALL'},activity:null,order:null,admin:null,adminPerson:'',config:null};}
function targetInputNumber(value){
 if(value===null||value==='')return '';
 if(typeof value==='number'){if(!Number.isFinite(value)||value<0)throw Error('Angka tidak valid.');return String(value);}
 let s=String(value).replace(/[\s\u00a0]/g,'');if(!s)return '';
 if(/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s))s=s.replace(/\./g,'').replace(',','.');
 else if(/^\d+(,\d+)?$/.test(s))s=s.replace(',','.');
 else if(!/^\d+\.\d{1,2}$/.test(s))throw Error('Angka tidak valid. Contoh: 6.500 untuk ribuan, 6,5 untuk desimal.');
 const n=Number(s);if(!Number.isFinite(n)||n<0)throw Error('Angka tidak valid.');return String(n);
}
function tmOptions(values,current,all){return (all?`<option value="ALL">${esc(all)}</option>`:'')+values.map(v=>{const value=typeof v==='object'?v.value:v,label=typeof v==='object'?v.label:v;return `<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('');}
function tmToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function uRoleIsTelemarketing(){return BOOT?.user.role==='TELEMARKETING';}
function tmIsMe(){return BOOT?.user.role==='TELEMARKETING';}
function tmHasTabs(){return !tmIsMe()&&tmMenuAllowed('tmactivity',BOOT?.user.role)&&['kpi','peringkat'].includes(PAGE);}
function tmAttachTabs(v){if(!tmHasTabs()||v.querySelector('.tm-role-tabs'))return;v.insertAdjacentHTML('afterbegin',`<div class="toolbar tm-role-tabs" role="tablist"><button class="chip ${tmState.tab==='sales'?'primary':''}" role="tab" aria-selected="${tmState.tab==='sales'}" data-tm-tab="sales">Sales</button><button class="chip ${tmState.tab==='tele'?'primary':''}" role="tab" aria-selected="${tmState.tab==='tele'}" data-tm-tab="tele">Telemarketing</button></div>`);v.querySelectorAll('[data-tm-tab]').forEach(b=>b.onclick=()=>{tmState.tab=b.dataset.tmTab;render();});}
async function tmRenderPage(v,seq){
 if(PAGE==='tmorder'){await tmOrderPage(v,seq);return true;}
 if(tmIsMe()&&['beranda','tmfu','kpi','peringkat'].includes(PAGE)){
  if(PAGE==='kpi')await tmKpiPage(v,seq);else if(PAGE==='peringkat')await tmRankPage(v,seq);else if(PAGE==='tmorder')await tmOrderPage(v,seq);else await tmActivityPage(v,seq,PAGE==='beranda');return true;
 }
 if(PAGE==='tmactivity'){await tmActivityPage(v,seq,false);return true;}
 if(tmHasTabs()&&tmState.tab==='tele'){if(PAGE==='kpi')await tmKpiPage(v,seq);else await tmRankPage(v,seq);tmAttachTabs(v);return true;}
 return false;
}
async function tmEnsureBoot(){if(!tmState.boot)tmState.boot=await rpc(tmIsMe()?'apiTMBoot':'apiOrderBoot',TOKEN);return tmState.boot;}
async function tmActivityPage(v,seq,home){
 v.innerHTML='<p class="v6load">Memuat aktivitas Telemarketing…</p>';const r=await rpc('apiTMActivity',TOKEN,REPORT.period,tmIsMe()?BOOT.user.nik:tmState.person,tmState.filters);if(seq!==SEQUENCE)return;tmState.activity=r;tmState.person=r.nik;
 const labels={ALL:'Semua status FU',NEVER:'Belum pernah FU',STALE:'Lama tidak FU',OVERDUE:'Jadwal lewat',TODAY:'FU hari ini',OK:'Terpantau'};
 const allPairs=tmIsMe()?(await tmEnsureBoot()).pairs:r.dealers;const brands=sortedUnique(allPairs.map(x=>x.brand));
 const regionSource=tmIsMe()?(tmState.boot.dealers.map(d=>({big:d.bigRegion,region:d.subRegion}))):r.dealers;
 v.innerHTML=(!tmIsMe()?`<div class="toolbar"><label>Telemarketing<select class="fi" id="tmPerson">${tmOptions(r.people.map(p=>({value:p.nik,label:p.nama})),r.nik)}</select></label><span class="hint">${r.scopeCount||0} pasangan dealer–brand terlihat dari ${r.totalAssigned||0} penugasan. KPI pribadi tetap utuh.</span></div>`:'')+`<div class="toolbar tm-filterbox"><label>Cari dealer / kode / Sales<input class="fi" id="tmSearch" value="${esc(tmState.filters.q)}" placeholder="Nama atau kode dealer"></label><label>Brand<select class="fi" id="tmBrand">${tmOptions(brands,tmState.filters.brand,'Semua brand')}</select></label><label>Big Region<select class="fi" id="tmBig">${tmOptions(sortedUnique(regionSource.map(x=>x.big)),tmState.filters.big,'Semua Big Region')}</select></label><label>Region<select class="fi" id="tmRegion">${tmOptions(sortedUnique(regionSource.filter(x=>tmState.filters.big==='ALL'||x.big===tmState.filters.big).map(x=>x.region)),tmState.filters.region,'Semua region')}</select></label><label>Status FU<select class="fi" id="tmStatus">${tmOptions(Object.entries(labels).filter(([k])=>k!=='ALL').map(([value,label])=>({value,label})),tmState.filters.state,'Semua status FU')}</select></label><button class="chip primary" id="tmFilter">Tampilkan</button></div>`;
 const queue=r.dealers||[],count=s=>queue.filter(x=>x.state===s).length;
 v.innerHTML+=cards([['Perlu FU hari ini',num(count('TODAY')+count('NEVER')),'Jadwal hari ini + belum pernah FU','tmactivity'],['FU terlambat',num(count('OVERDUE')),'Jadwal berikutnya sudah lewat','tmactivity'],['Belum pernah FU',num(count('NEVER')),'Sejak tanggal penugasan','tmfu'],['Form Order',num(r.orders.length),'Bulan '+bulan(REPORT.period),'tmorder']]);
 if(home){const k=await rpc('apiTMKpi',TOKEN,REPORT.period);if(seq!==SEQUENCE)return;v.innerHTML+=panel('KPI Telemarketing',kpiHtml(k.kpi),'Aktual otomatis dari transaksi resmi dealer–brand penugasan');v.innerHTML+=`<div class="toolbar"><button class="chip primary" id="tmNewOrder">+ Catat order</button><button class="chip" id="tmAllFU">Daftar Follow Up</button></div>`;}
 const qTable=table(['Dealer','Brand','Sales / Region','Terakhir FU','Umur FU','Jadwal berikutnya','Status','Aksi'],queue.map(d=>[tmIsMe()?customerButton({id:d.dealer,nama:d.name,kota:d.region}):esc(d.name)+'<small class="cellsub">'+esc(d.dealer)+'</small>',esc(d.brand),esc(d.sales)+'<small class="cellsub">'+esc(d.big+' / '+d.region)+'</small>',d.last?tgl(d.last):'Belum pernah',num(d.age)+' hari',d.next?tgl(d.next):'—',`<span class="tm-tag tm-${d.state.toLowerCase()}">${esc(labels[d.state])}${d.state==='OVERDUE'&&d.next?' '+Math.max(1,Math.round((new Date(tmToday()+'T00:00:00')-new Date(d.next+'T00:00:00'))/864e5))+' hari':''}</span>`,tmIsMe()?`<button class="chip" data-tm-fu="${esc(d.dealer)}" data-tm-brand="${esc(d.brand)}">Catat FU</button> <button class="chip" data-tm-order="${esc(d.dealer)}">Order</button>`:'—']));
 const fTable=table(['Tanggal','Dealer','Brand','Metode','Hasil','Catatan','FU berikutnya'],r.fu.map(f=>[tgl(f.date),esc(f.dealer),esc(f.brand),esc(f.method),esc(f.result),esc(f.note),f.next?tgl(f.next):'—']));
 const empty=!r.totalAssigned?`<div class="tm-empty"><b>Belum ada penugasan dealer–brand.</b><br>Minta Admin menugaskan lewat Admin › User &amp; Akses.</div>`:'';
 const tabs=[['q','Prioritas Follow Up',queue.length,qTable],['f','Riwayat FU',r.fu.length,fTable],['o','Form Order',r.orders.length,tmOrdersTable(r.orders)]],cur=tmState.area||'q';
 v.innerHTML+=panel('Aktivitas',empty||`<div class="tm-areatabs" role="tablist">${tabs.map(t=>`<button type="button" role="tab" class="${t[0]===cur?'on':''}" data-tm-area="${t[0]}">${t[1]} · ${num(t[2])}</button>`).join('')}</div>${tabs.map(t=>`<div class="table-scroll tm-area" data-area="${t[0]}" ${t[0]===cur?'':'hidden'}>${t[3]}</div>`).join('')}`,'Transaksi resmi tidak mengubah umur FU');
 v.querySelectorAll('[data-tm-area]').forEach(b=>b.onclick=()=>{tmState.area=b.dataset.tmArea;v.querySelectorAll('[data-tm-area]').forEach(x=>x.classList.toggle('on',x===b));v.querySelectorAll('.tm-area').forEach(x=>x.hidden=x.dataset.area!==b.dataset.tmArea);});
 $('tmPerson')?.addEventListener('change',e=>{tmState.person=e.target.value;tmState.filters={q:'',brand:'ALL',big:'ALL',region:'ALL',state:'ALL'};render();});
 $('tmFilter').onclick=()=>{tmState.filters={q:$('tmSearch').value.trim(),brand:$('tmBrand').value,big:$('tmBig').value,region:$('tmRegion').value,state:$('tmStatus').value};render();};
 $('tmBig').onchange=()=>{$('tmRegion').innerHTML=tmOptions(sortedUnique(regionSource.filter(x=>$('tmBig').value==='ALL'||x.big===$('tmBig').value).map(x=>x.region)),'ALL','Semua region');};
 $('tmSearch').onkeydown=e=>{if(e.key==='Enter')$('tmFilter').click();};
 if(home){$('tmNewOrder').onclick=()=>tmOpenOrder();$('tmAllFU').onclick=()=>{tmState.area='q';navigateTo('tmactivity');};}
 tmBindActivity(v,r);bind();
}
function tmBindActivity(v,r){v.querySelectorAll('[data-tm-fu]').forEach(b=>b.onclick=()=>tmFollowUpForm(b.dataset.tmFu,b.dataset.tmBrand));v.querySelectorAll('[data-tm-order]').forEach(b=>b.onclick=()=>tmOpenOrder(b.dataset.tmOrder));v.querySelectorAll('[data-tm-preview]').forEach(b=>b.onclick=()=>tmPreviewOrder(r.orders.find(o=>o.id===b.dataset.tmPreview)));v.querySelectorAll('[data-tm-editorder]').forEach(b=>b.onclick=()=>{tmState.order=structuredClone(r.orders.find(o=>o.id===b.dataset.tmEditorder));navigateTo('tmorder');});}
async function tmFollowUpForm(dealer,brand){
 modal('Catat Follow Up',`<form id="tmFUForm"><div class="userForm"><label>Dealer<input class="fi" value="${esc(dealer)}" readonly></label><label>Brand<input class="fi" value="${esc(brand)}" readonly></label><label>Tanggal FU<input class="fi" type="date" name="date" value="${tmToday()}" max="${tmToday()}" required></label><label>Metode<select class="fi" name="method">${tmOptions(['WhatsApp','Telepon','Kunjungan','Lainnya'],'WhatsApp')}</select></label><label>Hasil FU<input class="fi" name="result" list="tmFUResults" placeholder="Tulis atau pilih hasil FU" maxlength="180" required><datalist id="tmFUResults">${['Berminat order','Belum membutuhkan','Tidak terhubung','Minta dihubungi kembali','Menunggu stok','Order dicatat'].map(s=>`<option>${s}</option>`).join('')}</datalist></label><label>FU berikutnya<input class="fi" type="date" name="next"></label></div><label>Catatan<textarea class="fi" name="note" rows="3" maxlength="4000"></textarea></label><p id="tmFUError" class="hint" role="alert"></p><button class="chip primary">Simpan FU</button></form>`);
 $('tmFUForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await rpc('apiTMFollowUpSave',TOKEN,{...Object.fromEntries(new FormData(e.target)),dealer,brand});closeModal();await render();}catch(err){$('tmFUError').textContent=err.message;}finally{b.disabled=false;}};
}
async function tmKpiPage(v,seq){
 v.innerHTML='<p class="v6load">Memuat KPI Telemarketing…</p>';
 if(tmIsMe()){const r=await rpc('apiTMKpi',TOKEN,REPORT.period);if(seq!==SEQUENCE)return;v.innerHTML=panel('KPI saya · Telemarketing',tmKpiHtml(r.kpi),'Target dan aktual manual diisi Admin PIC');tmKpiDetails(v,r);v.innerHTML+=`<div class="toolbar"><button class="chip" id="tmPeerKpi">Lihat KPI Telemarketing lainnya</button></div>`;$('tmPeerKpi').onclick=()=>navigateTo('peringkat');}
 else{const rows=await rpc('apiTMRank',TOKEN,REPORT.period);if(seq!==SEQUENCE)return;v.innerHTML=panel('KPI Telemarketing',table(['Nama','KPI akhir','Status','Rincian'],rows.map(p=>[esc(p.nama),p.score==null?'—':decimal(p.score),esc(p.status),`<button class="chip" data-tm-kpi="${esc(p.nik)}">Lihat indikator</button>`])),'KPI pribadi lengkap; rincian dealer mengikuti kewenangan area');v.querySelectorAll('[data-tm-kpi]').forEach(b=>b.onclick=()=>tmPersonKpi(b.dataset.tmKpi));}
 v.querySelectorAll('section.panel').forEach(el=>el.dataset.v2SkipFold='1');
}
function tmKpiHtml(k,limited=false){
 if(!k.groups.length)return '<div class="empty">Kebijakan KPI Telemarketing belum diisi untuk periode ini.</div>';
 const val=n=>n==null?'—':num(n),score=n=>n==null?'—':pct(n);
 return `<div class="scorehead"><b>${score(k.score)}</b><span>KPI Telemarketing · ${esc(k.status)}<br>Rata-rata kelompok yang berlaku</span></div>`+k.groups.map(g=>{
  const active=g.indicators.filter(i=>i.state==='BERLAKU'),weight=active.reduce((n,i)=>n+i.weight,0);
  const rows=g.indicators.map(i=>{const label=esc(i.label)+(i.types?.length?'<small class="cellsub">TYPE: '+i.types.map(esc).join(', ')+'</small>':'')+(!limited&&i.metric==='DA'?'<small class="cellsub">Minimum '+num(i.minQty)+' unit / dealer–brand</small>':'');const points=i.score==null||i.state!=='BERLAKU'||!weight?null:i.score*i.weight/weight;return limited?[label,pct(i.weight),i.ach==null?'—':bar(i.ach),score(points)]:[label,pct(i.weight),val(i.target)+' / '+val(i.actual),i.ach==null?'—':bar(i.ach),score(points),esc(i.state)];});
  return `<details class="kgroup" open><summary>${esc(g.name)} <b>${score(g.score)}</b></summary>${table(limited?['Indikator','Bobot','Capaian','Skor Bobot']:['Indikator','Bobot dasar','Target / Aktual','Capaian','Skor berbobot','Status'],rows)}</details>`;
 }).join('')+'<div class="info">Target 0 tidak diwajibkan. Target atau aktual kosong belum final. Bobot indikator yang berlaku dinormalisasi dalam kelompok; KPI akhir merupakan rata-rata skor kelompok.</div>';
}
function tmKpiDetails(v,r){if(r.limited)return;const rows=[];for(const g of r.kpi.groups)for(const i of g.indicators){const details=r.kpi.details?.[i.id]||[];rows.push([esc(i.label),esc(i.source==='MANUAL'?'Input manual Admin':'Transaksi resmi Sales'),details.length?details.map(d=>esc(d.dealer)+' ('+num(d.qty)+' unit)').join(', '):'—']);}v.insertAdjacentHTML('beforeend',panel('Asal perhitungan indikator',table(['Indikator','Sumber aktual','Dealer yang berkontribusi'],rows),'IDDLE = tepat 2 bulan tanpa transaksi, bulan sebelumnya ada transaksi'));}
async function tmPersonKpi(nik){try{const r=await rpc('apiTMKpi',TOKEN,REPORT.period,nik,$('tmRankBrand')?.value||'ALL');modal('KPI · '+r.person.nama,tmKpiHtml(r.kpi,r.limited));const body=$('mbody');tmKpiDetails(body,r);}catch(e){fail(e);}}
async function tmRankPage(v,seq){
 const boot=tmIsMe()?await tmEnsureBoot():null;const brands=boot?sortedUnique(boot.pairs.map(p=>p.brand)):REPORT.brands.map(b=>b.brand);
 v.innerHTML=`<div class="toolbar"><label>Brand<select class="fi" id="tmRankBrand">${tmOptions(brands,'ALL','Seluruh KPI')}</select></label></div><div id="tmRankRows"></div>`;
 const draw=async()=>{const brand=$('tmRankBrand').value,rows=await rpc('apiTMRank',TOKEN,REPORT.period,brand);if(seq!==SEQUENCE)return;$('tmRankRows').innerHTML=panel('Peringkat Telemarketing',table(['Peringkat','Telemarketing','KPI','Status'],rows.map(p=>[p.rank||'—',`<button class="textlink ${p.mine?'tm-me':''}" data-tm-kpi="${esc(p.nik)}">${esc(p.nama)}${p.mine?' · Saya':''}</button>`,p.score==null?'—':decimal(p.score),esc(p.status)])),'KPI belum final belum memperoleh posisi peringkat');$('tmRankRows').querySelectorAll('[data-tm-kpi]').forEach(b=>b.onclick=()=>tmPersonKpi(b.dataset.tmKpi));};$('tmRankBrand').onchange=()=>draw().catch(fail);await draw();
}
function tmOrdersTable(orders){return table(['Nomor / Tanggal','Dealer','Sales person','Region / Refnote','Status','Dokumen'],orders.map(o=>[esc(o.number)+'<small class="cellsub">'+tgl(o.date)+'</small>',esc(o.dealerSnapshot?.name),esc(o.sales),esc(o.region)+'<small class="cellsub">'+esc(o.refnote||'—')+'</small>',esc(o.status),`<button class="chip" data-tm-preview="${esc(o.id)}">Pratinjau / PDF</button>${tmIsMe()?` <button class="chip" data-tm-editorder="${esc(o.id)}">Edit</button>`:''}`]));}
function tmEmptyItem(){return {uid:crypto.randomUUID(),mode:'manual',product:'',name:'',brand:'',color:'Hitam',qty:1,price:''};}
function tmNewOrder(dealer=''){const b=tmState.boot,bu=b.businesses[0],d=b.dealers.find(d=>d.id===dealer);return {id:'',revision:0,number:'Nomor otomatis setelah disimpan',date:tmToday(),businessId:bu?.id||'',businessSnapshot:bu||null,company:bu?.name||'',dealerMode:dealer?'master':'manual',dealer,manualDealer:{name:'',owner:'',phone:'',address:''},dealerSnapshot:d?{id:d.id,name:d.name,owner:d.owner,phone:d.phone,address:d.address}:null,sales:BOOT.user.role==='SALES'?BOOT.user.nama:(d?.sales||BOOT.user.nama),region:d?.subRegion||b.regions?.[0]||'',refnote:'-',notes:'',createdBy:BOOT.user.nama,showPrice:true,creditMode:'NOMINAL',creditNote:0,payment:'CBD',topDays:0,status:'DRAFT',items:[tmEmptyItem()]};}
async function tmOpenOrder(dealer=''){await tmEnsureBoot();tmState.order=tmNewOrder(dealer);closeModal();navigateTo('tmorder');}
function tmOrderFilterBar(){return `<div class="toolbar tm-ofilter"><label>Dari tanggal<input class="fi" type="date" id="tmOfFrom"></label><label>Sampai tanggal<input class="fi" type="date" id="tmOfTo"></label><label class="tm-of-dealer">Cari dealer<input class="fi" id="tmOfDealer" placeholder="Nama / kode dealer"></label><div class="tm-of-quick"><button class="chip" type="button" data-tm-of="today">Hari ini</button><button class="chip" type="button" data-tm-of="7">7 hari</button><button class="chip" type="button" data-tm-of="month">Bulan ini</button><button class="chip" type="button" data-tm-of="reset">Reset</button></div></div><p class="hint" id="tmOfInfo"></p>`;}
function tmOrderFilterInit(v,r){
 const all=r.orders||[],$f=id=>document.getElementById(id);if(!$f('tmOfFrom'))return;
 const apply=()=>{const f=$f('tmOfFrom').value,t=$f('tmOfTo').value,q=$f('tmOfDealer').value.trim().toLowerCase();
  const rows=all.filter(o=>(!f||String(o.date)>=f)&&(!t||String(o.date)<=t)&&(!q||((o.dealerSnapshot?.name||'')+' '+(o.dealerSnapshot?.id||'')).toLowerCase().includes(q)));
  $f('tmOrderRows').innerHTML=tmOrdersTable(rows);tmBindActivity(v,{...r,orders:rows});
  const dl=new Set(rows.map(o=>o.dealerSnapshot?.id||o.dealerSnapshot?.name)).size;
  $f('tmOfInfo').textContent=rows.length===all.length?`${all.length} order · ${dl} dealer (periode ${REPORT.period})`:`${rows.length} dari ${all.length} order · ${dl} dealer`;};
 const iso=d=>d.toISOString().slice(0,10),today=tmToday();
 const quick=k=>{const t=new Date(today+'T12:00:00Z');if(k==='reset'){$f('tmOfFrom').value='';$f('tmOfTo').value='';$f('tmOfDealer').value='';}else if(k==='today'){$f('tmOfFrom').value=today;$f('tmOfTo').value=today;}else if(k==='7'){const f=new Date(t);f.setUTCDate(f.getUTCDate()-6);$f('tmOfFrom').value=iso(f);$f('tmOfTo').value=today;}else{$f('tmOfFrom').value=today.slice(0,8)+'01';$f('tmOfTo').value=today;}apply();};
 ['tmOfFrom','tmOfTo'].forEach(id=>$f(id).onchange=apply);$f('tmOfDealer').oninput=apply;
 v.querySelectorAll('[data-tm-of]').forEach(b=>b.onclick=()=>quick(b.dataset.tmOf));apply();
}
async function tmOrderPage(v,seq){
 await tmEnsureBoot();if(seq!==SEQUENCE)return;const r=tmIsMe()?await rpc('apiTMActivity',TOKEN,REPORT.period,BOOT.user.nik):{orders:await rpc('apiOrderList',TOKEN,REPORT.period)};if(seq!==SEQUENCE)return;
 v.innerHTML=`<div class="toolbar"><button class="chip primary" id="tmOrderNew">+ Order baru</button><button class="chip" id="tmOrderClose">Daftar order</button></div><div id="tmOrderEditor"></div><div id="tmOrderList">${panel('Form Order',tmOrderFilterBar()+'<div id="tmOrderRows">'+tmOrdersTable(r.orders)+'</div>')}</div>`;
 $('tmOrderNew').onclick=()=>{tmState.order=tmNewOrder();tmDrawOrder();};$('tmOrderClose').onclick=()=>{tmState.order=null;$('tmOrderEditor').innerHTML='';$('tmOrderList').hidden=false;};tmBindActivity(v,r);tmOrderFilterInit(v,r);if(tmState.order)tmDrawOrder();
}
function tmFormGroup(n,title,hint,body){return `<section class="panel tm-form-group" data-v2-skip-fold="1"><div class="ph"><span class="tm-group-number">${n}</span><h3>${esc(title)}</h3><span class="hint">${esc(hint)}</span></div><div class="pb">${body}</div></section>`;}
function tmDrawOrder(){
 const o=tmState.order,b=tmState.boot;if(!o)return;const d=o.dealerMode==='master'?b.dealers.find(d=>d.id===o.dealer):o.manualDealer;const field=(label,key,type='text')=>`<label>${label}<input class="fi" type="${type}" data-tm-field="${key}" value="${esc(o[key]??'')}"></label>`;
 $('tmOrderList').hidden=true;$('tmOrderEditor').innerHTML=`<form id="tmOrderForm"><div class="toolbar tm-sticky-actions"><button class="chip primary" type="submit">Simpan order</button><button class="chip" type="button" id="tmDraft">Simpan draft</button><button class="chip" type="button" id="tmPreview">Pratinjau PDF</button><span class="hint" id="tmOrderMsg"></span></div>`+
 tmFormGroup('01','Identitas order','Badan usaha, penjual, wilayah, dan referensi',`<div class="userForm"><label>Badan usaha<select class="fi" data-tm-field="businessId" required>${b.businesses.length?tmOptions(b.businesses.map(x=>({value:x.id,label:x.name})),o.businessId):'<option value="">Admin perlu menambahkan badan usaha</option>'}</select></label>${field('Tanggal order','date','date')}${field('Region','region')}${field('Refnote','refnote')}<label>Nomor order<input class="fi" value="${esc(o.number)}" readonly></label><label>Dibuat oleh<input class="fi" value="${esc(BOOT.user.nama)}" readonly></label></div>`)+
 tmFormGroup('02','Dealer & Sales person','Dealer terdaftar atau isi manual',`<div class="toolbar"><label><input type="radio" name="tmDealerMode" value="master" ${o.dealerMode==='master'?'checked':''}> Dealer terdaftar</label><label><input type="radio" name="tmDealerMode" value="manual" ${o.dealerMode==='manual'?'checked':''}> Dealer baru / manual</label></div>${o.dealerMode==='master'?`<label>Cari nama / kode dealer<input class="fi" list="tmDealerList" id="tmDealerFind" value="${esc(d?d.name+' · '+d.id:'')}" placeholder="Ketik nama atau kode dealer"><datalist id="tmDealerList">${b.dealers.map(d=>`<option value="${esc(d.name+' · '+d.id)}"></option><option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</datalist></label>${d?`<div class="tm-dealer-info"><b>${esc(d.name)}</b><p>${esc(d.owner||'—')} · ${esc(d.phone||'—')}</p><p>${esc(d.address||'—')}</p></div>`:'<p class="hint">Pilih salah satu dealer penugasan.</p>'}`:`<div class="userForm">${[['Nama dealer','name'],['PIC / pemilik','owner'],['Nomor HP','phone'],['Alamat','address']].map(([label,key])=>`<label>${label}<input class="fi" data-tm-dealerfield="${key}" value="${esc(o.manualDealer[key]||'')}"></label>`).join('')}</div>`}<div class="tm-seller-row"><label>Sales person / penjual<input class="fi" list="tmSalesList" data-tm-field="sales" value="${esc(o.sales)}" placeholder="Sales, Telemarketing sendiri, atau nama manual"><datalist id="tmSalesList"><option value="${esc(BOOT.user.nama)}">Telemarketing sendiri</option>${b.sales.map(p=>`<option value="${esc(p.nama)}">${esc(p.nik)}</option>`).join('')}</datalist></label><small class="hint">Default PIC dealer, bisa diganti nama Telemarketing sendiri atau diketik manual. Tampil di PDF.</small></div>`)+
 tmFormGroup('03','Barang pesanan','Campurkan barang master dan barang baru dalam satu order',`<div id="tmOrderItems">${o.items.map((i,n)=>tmItemHtml(i,n,b)).join('')}</div><button class="chip" type="button" id="tmItemAdd">+ Tambah barang</button><div class="tm-order-total" id="tmOrderTotal"></div>`)+
 tmFormGroup('04','Catatan & dokumen','Harga opsional; Form Order tidak menambah aktual KPI',`<label>Catatan<textarea class="fi" data-tm-field="notes" maxlength="4000" rows="3">${esc(o.notes)}</textarea></label><label class="confirm"><input type="checkbox" data-tm-field="showPrice" ${o.showPrice?'checked':''}> Sertakan harga dan total rupiah di PDF</label>`)+`<p class="hint" id="tmOrderError" role="alert"></p></form>`;
 $('tmOrderForm').querySelectorAll('[data-tm-field]').forEach(el=>el.onchange=()=>{o[el.dataset.tmField]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.tmField==='businessId'){const bu=b.businesses.find(x=>x.id===el.value);o.businessSnapshot=bu;o.company=bu?.name||'';}tmDrawTotals();});
 $('tmOrderForm').querySelectorAll('[name=tmDealerMode]').forEach(el=>el.onchange=()=>{tmCollectOrder();o.dealerMode=el.value;setTimeout(()=>tmDrawOrder(),0);});
 $('tmDealerFind')?.addEventListener('change',e=>{const raw=e.target.value,hit=b.dealers.find(x=>x.id===raw||x.name===raw||x.name+' · '+x.id===raw);if(!hit){$('tmOrderError').textContent='Pilih dealer dari daftar penugasan.';return;}tmCollectOrder();o.dealer=hit.id;o.dealerSnapshot={id:hit.id,name:hit.name,owner:hit.owner,phone:hit.phone,address:hit.address};o.sales=hit.sales||BOOT.user.nama;o.region=hit.subRegion||hit.region||'';setTimeout(()=>tmDrawOrder(),0);});
 $('tmOrderForm').querySelectorAll('[data-tm-dealerfield]').forEach(el=>el.oninput=()=>o.manualDealer[el.dataset.tmDealerfield]=el.value);
 $('tmOrderForm').querySelectorAll('[data-tm-item-mode]').forEach(el=>el.onchange=()=>{tmCollectOrder();const i=o.items.find(x=>x.uid===el.dataset.tmItemMode);i.mode=el.value;i.product='';i.name='';i.brand='';setTimeout(()=>tmDrawOrder(),0);});
 $('tmOrderForm').querySelectorAll('[data-tm-product]').forEach(el=>el.onchange=()=>{const i=o.items.find(x=>x.uid===el.dataset.tmProduct),raw=el.value,p=b.products.find(p=>p.id===raw||p.name===raw||p.name+' · '+p.id===raw);if(!p){$('tmOrderError').textContent='Pilih produk master atau ubah ke barang baru.';return;}tmCollectOrder();Object.assign(i,{product:p.id,name:p.name,brand:p.brand});setTimeout(()=>tmDrawOrder(),0);});
 $('tmOrderForm').querySelectorAll('[data-tm-item-field]').forEach(el=>el.oninput=()=>{const i=o.items.find(x=>x.uid===el.dataset.uid);i[el.dataset.tmItemField]=el.value;tmDrawTotals();});
 $('tmOrderForm').querySelectorAll('[data-tm-remove]').forEach(el=>el.onclick=()=>{tmCollectOrder();o.items=o.items.filter(x=>x.uid!==el.dataset.tmRemove);setTimeout(()=>tmDrawOrder(),0);});
 $('tmItemAdd').onclick=()=>{tmCollectOrder();o.items.push(tmEmptyItem());tmDrawOrder();};$('tmPreview').onclick=()=>{tmCollectOrder();if(tmValidateOrder(o))tmPreviewOrder(o);};$('tmDraft').onclick=()=>tmSaveOrder('DRAFT');$('tmOrderForm').onsubmit=e=>{e.preventDefault();tmSaveOrder('SAVED');};tmDrawTotals();
}
function tmItemHtml(i,n,b){return `<article class="tm-order-item"><div class="ph"><h3>Barang ${n+1}</h3><span class="hint">${esc(i.mode==='master'?'Master produk':'Barang baru / manual')}</span><button class="chip" type="button" data-tm-remove="${esc(i.uid)}">Hapus</button></div><div class="pb"><div class="userForm"><label>Sumber barang<select class="fi" data-tm-item-mode="${esc(i.uid)}">${tmOptions([{value:'master',label:'Dari master'},{value:'manual',label:'Barang baru / manual'}],i.mode)}</select></label><label>Nama barang / kode${i.mode==='master'?`<input class="fi" list="tmProductList-${esc(i.uid)}" data-tm-product="${esc(i.uid)}" value="${esc(i.product?i.name+' · '+i.product:'')}" placeholder="Ketik nama atau kode produk"><datalist id="tmProductList-${esc(i.uid)}">${b.products.map(p=>`<option value="${esc(p.name+' · '+p.id)}"></option><option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</datalist>`:`<input class="fi" data-tm-item-field="name" data-uid="${esc(i.uid)}" value="${esc(i.name)}" maxlength="180" placeholder="Nama barang belum di master">`}</label><label>Brand<input class="fi" data-tm-item-field="brand" data-uid="${esc(i.uid)}" value="${esc(i.brand)}" ${i.mode==='master'?'readonly':''}></label><label>Warna<input class="fi" list="tmColors" data-tm-item-field="color" data-uid="${esc(i.uid)}" value="${esc(i.color)}" placeholder="Pilih atau ketik warna"></label><label>Jumlah (unit)<input class="fi" type="number" min="1" max="1000000" step="1" data-tm-item-field="qty" data-uid="${esc(i.uid)}" value="${esc(i.qty)}"></label><label>Harga satuan (opsional)<input class="fi" type="number" min="0" data-tm-item-field="price" data-uid="${esc(i.uid)}" value="${esc(i.price)}" placeholder="Belum diisi"></label></div><datalist id="tmColors"><option>Hitam</option><option>Putih</option><option>Biru</option><option>Hijau</option><option>Emas</option></datalist><p class="hint">Subtotal barang ${n+1}: <b id="tmSubtotal-${esc(i.uid)}">—</b></p></div></article>`;}
function tmCollectOrder(){const o=tmState.order;if(!o)return;document.querySelectorAll('#tmOrderForm [data-tm-field]').forEach(el=>o[el.dataset.tmField]=el.type==='checkbox'?el.checked:el.value);document.querySelectorAll('#tmOrderForm [data-tm-item-field]').forEach(el=>{const i=o.items.find(x=>x.uid===el.dataset.uid);if(i)i[el.dataset.tmItemField]=el.value;});document.querySelectorAll('#tmOrderForm [data-tm-dealerfield]').forEach(el=>o.manualDealer[el.dataset.tmDealerfield]=el.value);if(o.dealerMode==='manual')o.dealerSnapshot=structuredClone(o.manualDealer);}
function tmTotals(o){return {qty:o.items.reduce((n,i)=>n+(Number(i.qty)||0),0),amount:o.items.reduce((n,i)=>n+(Number(i.qty)||0)*(Number(i.price)||0),0),complete:o.items.every(i=>i.price!==''&&i.price!==null)};}
function tmDrawTotals(){const o=tmState.order,t=tmTotals(o);$('tmOrderTotal').innerHTML=`<strong>Total: ${num(t.qty)} unit</strong><strong>${t.complete?'Total harga':'Subtotal terisi'}: ${rupiah(t.amount)}</strong>`;o.items.forEach(i=>{const el=$('tmSubtotal-'+i.uid);if(el)el.textContent=i.price===''?'Belum diisi':rupiah(Number(i.qty)*Number(i.price));});}
function tmValidateOrder(o){const msg=!o.businessId?'Pilih badan usaha.':!(o.dealerSnapshot?.name)?'Pilih atau isi dealer.':!o.sales.trim()||!o.region.trim()?'Isi sales person dan region.':!o.items.length?'Tambahkan barang.':o.items.some(i=>!i.name||!i.brand||!i.color||!Number.isInteger(Number(i.qty))||Number(i.qty)<1||(i.mode==='master'&&!i.product))?'Lengkapi barang, brand, warna, dan jumlah minimal 1.':'';if(msg){$('tmOrderError').textContent=msg;return false;}return true;}
async function tmSaveOrder(status){tmCollectOrder();const o=tmState.order;if(!tmValidateOrder(o))return;const buttons=[...$('tmOrderForm').querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const saved=await rpc('apiTMOrderSave',TOKEN,{...o,status});tmState.order=saved;tmDrawOrder();$('tmOrderMsg').textContent=status==='DRAFT'?'Draft tersimpan.':'Order tersimpan.';}catch(e){$('tmOrderError').textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}}
function tmPreviewOrder(o){if(!o)return;const snapshot=structuredClone(o),pages=DSMTMPdf.layout(snapshot);modal('Pratinjau · '+snapshot.number,`<div class="toolbar tm-sticky-actions"><button class="chip primary" id="tmPdfDownload">Download PDF</button><span class="hint">Pratinjau dan PDF menggunakan layout yang sama.</span></div><div class="tm-pdf-preview">${DSMTMPdf.svg(pages)}</div>`);$('tmPdfDownload').onclick=()=>{const blob=new Blob([DSMTMPdf.pdf(pages)],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(snapshot.number==='Nomor otomatis setelah disimpan'?'Catatan_Order_Telemarketing':snapshot.number)+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}

async function tmAdminLoad(){tmState.admin=await rpc('apiTMAdmin',TOKEN);return tmState.admin;}
function tmAdminPanel(v){
 v.insertAdjacentHTML('beforeend',panel('Penugasan Telemarketing',`<div class="toolbar"><button class="chip primary" id="tmAdminLoad">Kelola Penugasan</button></div><div id="tmAdminBox"></div>`,'Admin PIC lintas region, penugasan dealer–brand, batas FU'));
 v.insertAdjacentHTML('beforeend',panel('KPI Telemarketing',`<div class="toolbar"><button class="chip primary" id="tmKpiLoad">Atur KPI Telemarketing</button></div><div id="tmKpiBox"></div>`,'Indikator, target, dan aktual per Telemarketing · terpisah dari KPI Sales'));
 v.insertAdjacentHTML('beforeend',panel('Badan usaha Form Order',`<div class="toolbar"><button class="chip" id="tmBusinessLoad">Muat badan usaha</button><button class="chip primary" id="tmBusinessAdd">+ Tambah badan usaha</button></div><div id="tmBusinessBox"></div>`,'Nama dan logo untuk Form Order / PDF'));
 $('tmAdminLoad').onclick=async()=>{try{const a=await tmAdminLoad();tmAdminDraw(a);}catch(e){$('tmAdminBox').textContent=e.message;}};
 $('tmKpiLoad').onclick=async()=>{try{const a=await tmAdminLoad();tmKpiPanelDraw(a);}catch(e){$('tmKpiBox').textContent=e.message;}};
 $('tmBusinessLoad').onclick=()=>tmBusinessLoad();$('tmBusinessAdd').onclick=()=>tmBusinessEditor();
}
function tmKpiPanelDraw(a){
 const people=a.people||[];if(!people.length){$('tmKpiBox').innerHTML='<p class="info">Belum ada Telemarketing dalam pengelolaan Anda.</p>';return;}
 const cur=people.find(p=>p.nik===tmState.adminPerson)||people[0];tmState.adminPerson=cur.nik;
 $('tmKpiBox').innerHTML=`<div class="tm-kpi-split"><aside class="tm-kpi-list"><input class="fi" id="tmKpiFind" placeholder="Cari Telemarketing…">${people.map(p=>`<button type="button" class="tm-kpi-person ${p.nik===cur.nik?'on':''}" data-tm-kpiperson="${esc(p.nik)}"><b>${esc(p.nama)}</b><small>${esc(p.nik)} · ${p.pairs.length} penugasan</small></button>`).join('')}</aside><div class="tm-kpi-main"><div class="toolbar"><label>Bulan KPI<input type="month" class="fi" id="tmAdminPeriod" value="${REPORT.period}"></label></div><div id="tmSettingsBox"></div></div></div>`;
 const open=()=>{const p=people.find(x=>x.nik===tmState.adminPerson);tmKpiEditor(p,$('tmAdminPeriod').value,a).catch(fail);};
 $('tmKpiBox').querySelectorAll('[data-tm-kpiperson]').forEach(b=>b.onclick=()=>{tmState.adminPerson=b.dataset.tmKpiperson;tmKpiPanelDraw(a);});
 $('tmKpiFind').oninput=e=>{const q=e.target.value.toLowerCase();$('tmKpiBox').querySelectorAll('[data-tm-kpiperson]').forEach(b=>b.style.display=b.textContent.toLowerCase().includes(q)?'':'none');};
 $('tmAdminPeriod').onchange=open;open();
}
function tmAdminDraw(a){
 const p=a.people.find(p=>p.nik===tmState.adminPerson)||a.people[0];tmState.adminPerson=p?.nik||'';
 $('tmAdminBox').innerHTML=(!a.people.length?'<p class="info">Belum ada Telemarketing dalam pengelolaan Anda. Super Admin menambahkan akun dengan jabatan TELEMARKETING dan memilih RGM sebagai Atasan Utama, lalu menetapkan Admin PIC.</p>':`<div class="toolbar"><label>Telemarketing<select class="fi" id="tmAdminPerson">${tmOptions(a.people.map(p=>({value:p.nik,label:p.nama+' · '+p.nik})),p.nik)}</select></label><button class="chip" id="tmProfileBtn">Admin PIC & batas FU</button><button class="chip" id="tmAssignmentBtn">Penugasan dealer–brand</button></div><p class="hint">${p.pairs.length} penugasan dealer–brand. Atasan utama: ${esc(p.atasan)}. Admin PIC: ${esc(p.profile.admin_pic||'belum ditetapkan')}.</p>`);
 if(!p)return;$('tmAdminPerson').onchange=e=>{tmState.adminPerson=e.target.value;tmAdminDraw(a);};$('tmProfileBtn').disabled=!a.superuser;$('tmProfileBtn').onclick=()=>tmProfileEditor(p,a);$('tmAssignmentBtn').onclick=()=>tmAssignmentEditor(p,a)
}
function tmProfileEditor(p,a){modal('Admin PIC · '+p.nama,`<form id="tmProfileForm"><div class="userForm"><label>Admin PIC<select class="fi" name="adminPic" required><option value="">Pilih Admin</option>${tmOptions(a.admins.map(x=>({value:x.nik,label:x.nama+' · '+x.role})),p.profile.admin_pic)}</select></label><label>Lama tidak FU (hari)<input type="number" min="1" max="365" class="fi" name="staleDays" value="${p.profile.stale_days}" required></label></div><p class="hint">Admin PIC mengelola target dan aktual manual seluruh penugasan Telemarketing, termasuk lintas RGM.</p><p id="tmProfileError" role="alert"></p><button class="chip primary">Simpan</button></form>`);$('tmProfileForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await rpc('apiTMProfileSave',TOKEN,p.nik,{...Object.fromEntries(new FormData(e.target)),revision:p.profile.revision});closeModal();tmAdminDraw(await tmAdminLoad());}catch(err){$('tmProfileError').textContent=err.message;}finally{b.disabled=false;}};}
function tmAssignmentEditor(p,a){
 const selected=new Map(p.pairs.map(x=>[x.dealer+'\u001f'+x.brand,{dealer:x.dealer,brand:x.brand}]));
 modal('Penugasan · '+p.nama,`<form id="tmAssignmentForm"><div class="userForm"><label>Mode penugasan<select class="fi" name="mode"><option value="SELECTED">Dealer pilihan → target manual</option><option value="ALL">Seluruh dealer Sales → target mengikuti Sales</option><option value="MIXED">Campuran → target manual terpisah</option></select></label><label>Brand untuk seluruh dealer Sales<select class="fi" id="tmAssignBrands" multiple size="4">${tmOptions(a.brands,'')}</select></label></div><details open><summary>Sales untuk penugasan seluruh dealer / campuran</summary><div class="regionChecks tm-scroll-list">${a.sales.map(s=>`<label><input type="checkbox" class="tm-assign-sales" value="${esc(s.nik)}"> ${esc(s.nama)} · ${esc(s.wilayah+' / '+(s.portfolio||s.region))}</label>`).join('')}</div></details><div class="toolbar"><label>Cari dealer<input class="fi" id="tmAssignSearch" placeholder="Nama / kode / Sales"></label><label>Big Region<select class="fi" id="tmAssignBig">${tmOptions(sortedUnique(a.dealers.map(d=>d.bigRegion)),'ALL','Semua Big Region')}</select></label><label>Region<select class="fi" id="tmAssignRegion"><option value="ALL">Semua region</option></select></label><label>Brand dealer pilihan<select class="fi" id="tmAssignBrand">${tmOptions(a.brands,a.brands[0])}</select></label></div><div id="tmAssignRows" class="tm-scroll-list"></div><p class="hint" id="tmAssignCount"></p><label class="confirm"><input type="checkbox" name="correctCurrent"> Koreksi cakupan KPI bulan berjalan</label><p class="hint">Akses dealer/FU langsung berubah. Cakupan KPI mulai bulan berikutnya; penugasan pertama mulai bulan ini jika belum masuk KPI pemegang lain. Perpindahan mengikuti bulan berikutnya. Koreksi bulan berjalan harus dinyatakan di atas. Histori bulan lama tetap utuh.</p><label>Alasan<input class="fi" name="reason" minlength="5" required></label><p id="tmAssignError" role="alert"></p><button class="chip primary">Simpan penugasan</button></form>`);
 const draw=()=>{const q=$('tmAssignSearch').value.trim().toLowerCase(),big=$('tmAssignBig').value,region=$('tmAssignRegion').value,brand=$('tmAssignBrand').value,rows=a.dealers.filter(d=>(big==='ALL'||d.bigRegion===big)&&(region==='ALL'||d.subRegion===region)&&(!q||(d.dealer+' '+d.nama+' '+d.sales).toLowerCase().includes(q)));$('tmAssignRows').innerHTML=rows.slice(0,200).map(d=>`<label class="tm-assignment-row"><input type="checkbox" data-tm-dealer-select="${esc(d.dealer)}" ${selected.has(d.dealer+'\u001f'+brand)?'checked':''}><span><b>${esc(d.nama)}</b><small>${esc(d.dealer+' · '+d.sales+' · '+d.bigRegion+' / '+d.subRegion)}</small></span><span class="tm-tag">${esc(brand)}</span></label>`).join('');$('tmAssignCount').textContent=selected.size+' pasangan dipilih · menampilkan '+Math.min(200,rows.length)+' dari '+rows.length+' dealer. Cari untuk mempersempit.';$('tmAssignRows').querySelectorAll('[data-tm-dealer-select]').forEach(el=>el.onchange=()=>{const k=el.dataset.tmDealerSelect+'\u001f'+brand;if(el.checked)selected.set(k,{dealer:el.dataset.tmDealerSelect,brand});else selected.delete(k);$('tmAssignCount').textContent=selected.size+' pasangan dipilih.';});};
 $('tmAssignSearch').oninput=draw;$('tmAssignBrand').onchange=draw;$('tmAssignRegion').onchange=draw;$('tmAssignBig').onchange=()=>{$('tmAssignRegion').innerHTML=tmOptions(sortedUnique(a.dealers.filter(d=>$('tmAssignBig').value==='ALL'||d.bigRegion===$('tmAssignBig').value).map(d=>d.subRegion)),'ALL','Semua region');draw();};draw();
 $('tmAssignmentForm').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button');b.disabled=true;try{const r=await rpc('apiTMAssignmentSave',TOKEN,p.nik,{...Object.fromEntries(new FormData(form)),revision:p.profile.revision,sales:[...form.querySelectorAll('.tm-assign-sales:checked')].map(e=>e.value),brands:[...$('tmAssignBrands').selectedOptions].map(e=>e.value),pairs:[...selected.values()],correctCurrent:form.elements.correctCurrent.checked});closeModal();tmAdminDraw(await tmAdminLoad());modal('Penugasan tersimpan',`<p>Akses dealer/FU sudah diperbarui. Cakupan KPI berlaku mulai <b>${esc(bulan(r.effectivePeriod))}</b>.</p>`);}catch(err){$('tmAssignError').textContent=err.message;}finally{b.disabled=false;}};
}
function tmDefaultIndicator(){return {id:crypto.randomUUID().replace(/-/g,'').slice(0,16),label:'SELL THRU',group:'KPI Telemarketing',metric:'QTY',brand:'ALL',weight:100,cap:100,target:null,actual:null,source:'AUTO',types:[],requirements:[],logic:'AND',minQty:1,inherit:true};}
async function tmKpiEditor(p,period,a){
 let cfg=await rpc('apiTMKpiSettings',TOKEN,p.nik,period),ind=structuredClone(cfg.indicators.length?cfg.indicators:[tmDefaultIndicator()]),reason='',busy=false;
 const opened=new Set(),numeric=['weight','cap','target','actual','minQty'];
 const metrics=[{value:'QTY',label:'SELL THRU'},{value:'DA',label:'Dealer Aktif'},{value:'NOO',label:'NOO'},{value:'IDDLE',label:'Dealer IDDLE'},{value:'OMZET',label:'OMZET'},{value:'MANUAL',label:'Khusus manual'}];
 const names={group:'Kelompok',metric:'Metrik',brand:'Brand',types:'Filter TYPE',minQty:'Minimum unit',weight:'Bobot',cap:'Batas skor',target:'Target',actual:'Aktual',source:'Sumber aktual',label:'Label',inherit:'Target dari Sales',salesIndicator:'ID indikator Sales',logic:'Gabungan aturan',requirements:'Aturan minimum'};
 const normalize=i=>({...i,types:i.types||[],requirements:i.requirements||[]});ind=ind.map(normalize);
 const field=(k,n)=>`data-tm-ki="${k}" data-n="${n}" aria-label="${names[k]} indikator ${n+1}"`;
 const input=(k,n,i,extra='')=>`<input class="fi ${numeric.includes(k)?'n':''}" ${field(k,n)} value="${esc(i[k]??'')}" ${numeric.includes(k)?'inputmode="decimal"':''} ${extra}>`;
 const parse=(el,i)=>{const k=el.dataset.tmKi,v=el.type==='checkbox'?el.checked:el.value;if(numeric.includes(k)){const value=targetInputNumber(v);i[k]=value===''?null:Number(value);}else if(k==='types')i[k]=v.split('|').map(x=>x.trim()).filter(Boolean);else if(k==='requirements'){i[k]=v.split('\n').filter(x=>x.trim()).map(l=>{const [brand,types,min]=l.split(';').map(x=>(x||'').trim());if(!brand||!min)throw Error('Aturan harus BRAND ; TYPE ; MINIMUM UNIT.');return {brand:brand.toUpperCase(),types:types.split('|').map(x=>x.trim()).filter(Boolean),minQty:Number(targetInputNumber(min))};});}else i[k]=v;};
 const collect=()=>{const next=structuredClone(ind);$('tmSettingsBox').querySelectorAll('[data-tm-ki]').forEach(el=>parse(el,next[+el.dataset.n]));ind=next;reason=$('tmKpiReason').value;};
 const showError=e=>{$('tmKpiError').textContent=e.message||String(e);};
 const sums=()=>{const weights={};ind.forEach(i=>{const g=i.group.trim()||'Belum ada kelompok';weights[g]=(weights[g]||0)+(Number(i.weight)||0);});$('tmKpiSums').innerHTML=Object.entries(weights).map(([g,w])=>`<span class="${Math.abs(w-100)>.001?'bad':''}">${esc(g)}: ${num(w)}% ${Math.abs(w-100)>.001?'· harus 100%':'✓'}</span>`).join('');return Object.values(weights).every(w=>Math.abs(w-100)<.001);};
 const draw=()=>{const target=$('tmSettingsBox');if(!target)return;
  target.innerHTML=`<div class="v6kEditorHead tm-kpi-head"><h4 class="v6kTitle">KPI ${esc(p.nama)} · ${esc(bulan(period))}</h4><p class="hint">Satu indikator satu baris. Target 0 = tidak diwajibkan; target atau aktual kosong = belum final. Klik Aturan untuk pengaturan tambahan.</p><span class="v6kTag">${ind.length} indikator</span> <span class="tm-tag">${esc({MIXED:"Campuran",SELECTED:"Dealer pilihan",ALL:"Seluruh dealer Sales"}[cfg.scope.mode]||cfg.scope.mode)} · ${cfg.scope.pairs.length} dealer–brand</span></div>
   <div class="table-scroll v6kEditorScroll tm-kpi-grid"><table class="v6kTable tm-kpi-table" data-sort-ready="1"><thead><tr><th>Kelompok</th><th>Metrik</th><th>Brand</th><th>Filter TYPE</th><th>Min unit</th><th>Bobot %</th><th>Batas skor</th><th>Target</th><th>Aktual</th><th>Sumber aktual</th><th>Label</th><th>Aksi</th></tr></thead><tbody id="tmKpiIndicators">${ind.map((i,n)=>{
   const auto=i.source!=='MANUAL',open=opened.has(i.id),inherited=auto&&cfg.scope.mode==='ALL'&&i.inherit;
   return `<tr class="tm-kpi-row ${i.metric==='IDDLE'?'v6kIddleRow':''}" data-tm-kpi-row="${n}"><td>${input('group',n,i,'placeholder="Kelompok KPI"')}</td>
    <td><select class="fi" ${field('metric',n)}>${tmOptions(metrics,i.metric)}</select></td>
    <td><select class="fi" ${field('brand',n)}>${tmOptions(['ALL',...a.brands],i.brand)}</select></td>
    <td><input class="fi" ${field('types',n)} value="${esc(i.types.join('|'))}" placeholder="Semua TYPE" title="Pisahkan TYPE dengan |, contoh P55|P65" ${i.metric==='IDDLE'?'disabled':''}></td>
    <td>${input('minQty',n,i,i.metric==='IDDLE'?'readonly title="IDDLE dihitung per dealer–brand setelah tepat 2 bulan kosong"':'title="Minimal unit per dealer–brand"')}</td>
    <td>${input('weight',n,i)}</td><td>${input('cap',n,i)}</td>
    <td>${input('target',n,i,'placeholder="Belum diisi" title="Target manual / fallback; kosong belum diisi, 0 tidak wajib"')}${inherited?'<small class="tm-kpi-cell-note">Sales / fallback</small>':''}</td>
    <td>${auto?'<span class="tm-kpi-auto" title="Aktual dihitung dari transaksi resmi Sales pada dealer–brand penugasan">Transaksi Sales</span>':input('actual',n,i,'placeholder="Belum diisi" title="Aktual manual; 0 merupakan nilai yang sah"')}</td>
    <td><select class="fi" ${field('source',n)} ${i.metric==='MANUAL'?'disabled':''}>${tmOptions([{value:'AUTO',label:'Transaksi Sales'},{value:'MANUAL',label:'Manual Admin'}],i.source)}</select></td>
    <td>${input('label',n,i,'placeholder="Nama indikator"')}</td><td class="tm-kpi-actions"><button type="button" class="chip" data-tm-kpi-rules="${n}" aria-expanded="${open}" aria-controls="tmRules${n}">Aturan${i.requirements.length?' ('+i.requirements.length+')':''}</button><button type="button" class="chip" data-tm-kpi-remove="${n}" title="Hapus indikator ${n+1}" aria-label="Hapus indikator ${n+1}">✕</button></td></tr>
    <tr class="tm-kpi-rules" id="tmRules${n}" ${open?'':'hidden'}><td colspan="12"><div class="tm-kpi-rule-fields"><label>ID indikator Sales (opsional)${input('salesIndicator',n,i,'placeholder="Untuk target indikator Sales khusus"')}</label><label>Gabungan aturan<select class="fi" ${field('logic',n)}>${tmOptions(['AND','OR'],i.logic)}</select></label><label class="confirm"><input type="checkbox" ${field('inherit',n)} ${i.inherit?'checked':''} ${cfg.scope.mode!=='ALL'||!auto?'disabled':''}> Target mengikuti Sales jika tersedia</label><label class="tm-kpi-rule-wide">Aturan minimum brand / TYPE<textarea class="fi" rows="2" ${field('requirements',n)} placeholder="ITEL ; P55|P65 ; 2">${esc(i.requirements.map(r=>r.brand+' ; '+r.types.join('|')+' ; '+r.minQty).join('\n'))}</textarea><small class="hint">Satu aturan per baris: BRAND ; TYPE1|TYPE2 ; MINIMUM UNIT. Kosongkan TYPE untuk semua TYPE.</small></label></div><p class="hint">Dealer pilihan / campuran memakai target manual terpisah. Indikator manual memakai target dan aktual dari Admin PIC. IDDLE: tepat 2 bulan penuh tanpa transaksi, lalu bulan ini kembali order.</p></td></tr>`;
  }).join('')||'<tr><td colspan="12" class="hint">Belum ada indikator. Klik + Indikator.</td></tr>'}</tbody></table></div>
   <div class="v6kSums" id="tmKpiSums"></div><div class="toolbar tm-kpi-toolbar"><button class="chip" type="button" id="tmKpiAdd">+ Indikator</button><button class="chip" type="button" id="tmKpiCopy">Salin kebijakan bulan sebelumnya</button></div>
   <div class="toolbar tm-kpi-save"><label>Alasan perubahan<input class="fi" id="tmKpiReason" value="${esc(reason)}" placeholder="Minimal 5 karakter"></label><button class="chip primary" type="button" id="tmKpiSave">Simpan KPI / target / aktual</button><span id="tmKpiError" role="status" aria-live="polite"></span></div>`;
  $('tmKpiReason').oninput=e=>reason=e.target.value;sums();
  target.querySelectorAll('[data-tm-ki]').forEach(el=>el.onchange=()=>{try{const n=+el.dataset.n,k=el.dataset.tmKi;collect();if(k==='metric'){if(ind[n].metric==='MANUAL')ind[n].source='MANUAL';if(ind[n].metric==='DA')ind[n].minQty=2;if(['NOO','IDDLE'].includes(ind[n].metric))ind[n].minQty=1;if(ind[n].metric==='IDDLE')ind[n].types=[];}if(k==='source'||k==='metric')draw();else sums();}catch(e){showError(e);el.focus();}});
  target.querySelectorAll('[data-tm-kpi-rules]').forEach(el=>el.onclick=()=>{const n=+el.dataset.tmKpiRules,row=$('tmRules'+n),open=row.hidden;row.hidden=!open;el.setAttribute('aria-expanded',String(open));if(open)opened.add(ind[n].id);else opened.delete(ind[n].id);});
  target.querySelectorAll('[data-tm-kpi-remove]').forEach(el=>el.onclick=()=>{try{collect();ind.splice(+el.dataset.tmKpiRemove,1);draw();}catch(e){showError(e);}});
  $('tmKpiAdd').onclick=()=>{try{collect();const i=tmDefaultIndicator();i.group=ind.at(-1)?.group||i.group;i.weight=0;ind.push(i);draw();}catch(e){showError(e);}};
  $('tmKpiCopy').onclick=async e=>{const b=e.target;b.disabled=true;try{collect();const d=new Date(period+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);const prev=await rpc('apiTMKpiSettings',TOKEN,p.nik,d.toISOString().slice(0,7));if(!prev.indicators.length)throw Error('Kebijakan bulan sebelumnya belum ada.');ind=structuredClone(prev.indicators).map(i=>normalize({...i,target:null,actual:null}));opened.clear();draw();}catch(err){showError(err);}finally{b.disabled=false;}};
  $('tmKpiSave').onclick=async()=>{if(busy)return;try{collect();if(reason.trim().length<5)throw Error('Isi alasan perubahan minimal 5 karakter.');if(!ind.length)throw Error('Tambahkan minimal satu indikator.');if(!sums())throw Error('Total bobot setiap kelompok harus 100%.');busy=true;$('tmKpiSave').disabled=true;cfg=await rpc('apiTMKpiSave',TOKEN,p.nik,period,{revision:cfg.revision,indicators:ind,reason});cfg=await rpc('apiTMKpiSettings',TOKEN,p.nik,period);ind=structuredClone(cfg.indicators).map(normalize);draw();$('tmKpiError').textContent='KPI tersimpan.';}catch(e){showError(e);}finally{busy=false;if($('tmKpiSave'))$('tmKpiSave').disabled=false;}};
 };draw();
}


async function tmBusinessLoad(){try{const a=await tmAdminLoad(),rows=a.businesses;$('tmBusinessBox').innerHTML=table(['Badan usaha','Logo','Status','Aksi'],rows.map(b=>[esc(b.name),b.logo?`<img src="${esc(b.logo.data)}" class="tm-business-logo" alt="Logo ${esc(b.name)}">`:'Belum diisi',b.active?'Aktif':'Nonaktif',`<button class="chip" data-tm-business="${esc(b.id)}">Edit</button>`]));$('tmBusinessBox').querySelectorAll('[data-tm-business]').forEach(el=>el.onclick=()=>tmBusinessEditor(rows.find(b=>b.id===el.dataset.tmBusiness)));}catch(e){$('tmBusinessBox').textContent=e.message;}}
function tmBusinessEditor(b={id:'',name:'',logo:null,active:true,revision:0}){let logo=b.logo;modal('Badan usaha Telemarketing',`<form id="tmBusinessForm"><label>Nama badan usaha<input class="fi" name="name" value="${esc(b.name)}" maxlength="180" required></label><label>Logo<input class="fi" type="file" id="tmBusinessLogo" accept="image/png,image/jpeg,image/webp"></label><div id="tmBusinessLogoPreview">${logo?`<img class="tm-business-logo" src="${esc(logo.data)}" alt="Pratinjau logo">`:''}</div><button type="button" class="chip" id="tmLogoRemove">Hapus logo</button><label class="confirm"><input type="checkbox" name="active" ${b.active?'checked':''}> Aktif</label><p class="hint">Logo tersimpan pada snapshot order; perubahan badan usaha tidak mengubah PDF order lama.</p><p id="tmBusinessError" role="alert"></p><button class="chip primary" type="submit">Simpan badan usaha</button></form>`);let loading=false;
 $('tmBusinessLogo').onchange=async e=>{const file=e.target.files[0];if(!file)return;loading=true;try{const img=await createImageBitmap(file),size=192,canvas=document.createElement('canvas');canvas.width=canvas.height=size;const c=canvas.getContext('2d');c.fillStyle='#ffffff';c.fillRect(0,0,size,size);const scale=Math.min(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;c.drawImage(img,(size-w)/2,(size-h)/2,w,h);img.close();logo={data:canvas.toDataURL('image/jpeg',.92),width:size,height:size};$('tmBusinessLogoPreview').innerHTML=`<img class="tm-business-logo" src="${logo.data}" alt="Pratinjau logo">`;}catch(e){$('tmBusinessError').textContent='Logo gagal dibaca.';}finally{loading=false;}};
 $('tmLogoRemove').onclick=()=>{logo=null;$('tmBusinessLogoPreview').innerHTML='';};$('tmBusinessForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=f.querySelector('button[type="submit"]'),error=$('tmBusinessError');if(loading){error.textContent='Tunggu logo selesai diproses.';return;}btn.disabled=true;error.textContent='Menyimpan badan usaha…';try{await rpc('apiTMBusinessSave',TOKEN,{id:b.id,name:f.querySelector('input[name="name"]').value.trim(),logo,active:f.querySelector('input[name="active"]').checked,revision:b.revision});closeModal();await tmBusinessLoad();}catch(err){error.textContent=err?.message||'Gagal menyimpan badan usaha.';}finally{btn.disabled=false;}};
}
function tmDealerActions(id){if(!tmIsMe())return;const body=$('mbody');if(!body||body.querySelector('.tm-dealer-actions'))return;body.insertAdjacentHTML('afterbegin',`<div class="toolbar tm-dealer-actions"><button class="chip primary" id="tmDealerFU">Catat FU</button><button class="chip" id="tmDealerOrder">Catat order</button></div>`);$('tmDealerOrder').onclick=()=>tmOpenOrder(id);$('tmDealerFU').onclick=async()=>{const b=await tmEnsureBoot(),brands=b.pairs.filter(p=>p.dealer===id).map(p=>p.brand);if(brands.length===1)tmFollowUpForm(id,brands[0]);else{modal('Pilih brand untuk FU',`<div class="toolbar">${brands.map(brand=>`<button class="chip" data-tm-fubrand="${esc(brand)}">${esc(brand)}</button>`).join('')}</div>`);$('mbody').querySelectorAll('[data-tm-fubrand]').forEach(el=>el.onclick=()=>tmFollowUpForm(id,el.dataset.tmFubrand));}};}
